#!/usr/bin/env node

/**
 * Update .env file with Cognito IDs from CDK stack outputs
 * This script runs automatically after CDK deployment via the cdk:deploy npm script
 * It reads from cdk-outputs.json (generated by --outputs-file flag)
 */

const fs = require('fs');
const path = require('path');

async function updateEnvFromCdkOutputs() {
  const outputsFile = path.join(__dirname, '..', 'cdk-outputs.json');
  
  // Check if outputs file exists
  if (!fs.existsSync(outputsFile)) {
    console.log('⚠️  No cdk-outputs.json found - skipping Cognito ID update');
    console.log('   This is normal if CDK deployment was skipped or failed');
    return;
  }
  
  console.log('📡 Reading CDK outputs from cdk-outputs.json');
  
  try {
    const outputs = JSON.parse(fs.readFileSync(outputsFile, 'utf-8'));
    
    // Find the Authentication stack outputs
    const authStackKey = Object.keys(outputs).find(key => key.includes('Authentication'));
    
    if (!authStackKey) {
      console.log('⚠️  No Authentication stack found in outputs - skipping Cognito update');
    }
    
    // Find the Connect stack outputs (must end with 'Connect' to avoid matching 'Authentication')
    const connectStackKey = Object.keys(outputs).find(key => key.endsWith('Connect'));
    
    if (!connectStackKey) {
      console.log('⚠️  No Connect stack found in outputs - skipping Contact Flow update');
    }
    
    if (!authStackKey && !connectStackKey) {
      console.log('⚠️  No relevant stacks found in outputs - skipping');
      return;
    }
    
    // Extract Cognito IDs from Authentication stack
    let userPoolId, clientId, identityPoolId;
    if (authStackKey) {
      const authOutputs = outputs[authStackKey];
      userPoolId = authOutputs.UserPoolIdOutput;
      clientId = authOutputs.UserPoolClientIdOutput;
      identityPoolId = authOutputs.IdentityPoolIdOutput;
      
      if (userPoolId && clientId && identityPoolId) {
        console.log('✅ Found Cognito IDs:');
        console.log(`   User Pool ID: ${userPoolId}`);
        console.log(`   Client ID: ${clientId}`);
        console.log(`   Identity Pool ID: ${identityPoolId}`);
        console.log('');
      } else {
        console.log('⚠️  Some Cognito outputs not found in Authentication stack');
        console.log('   Available outputs:', Object.keys(authOutputs).join(', '));
      }
    }
    
    // Extract Contact Flow IDs from Connect stack
    let webrtcFlowId, chatFlowId;
    if (connectStackKey) {
      const connectOutputs = outputs[connectStackKey];
      
      // Look for contact flow ID outputs
      // The stack exports them as WebRTCQueueRoutingIdOutput and ChatAgentRoutingIdOutput
      const webrtcFlowArn = connectOutputs.WebRTCQueueRoutingIdOutput;
      const chatFlowArn = connectOutputs.ChatAgentRoutingIdOutput;
      
      // Extract UUID from ARN (format: arn:aws:connect:region:account:instance/id/contact-flow/UUID)
      // Amazon Connect API requires just the UUID, not the full ARN
      if (webrtcFlowArn) {
        const match = webrtcFlowArn.match(/contact-flow\/([a-f0-9-]+)$/);
        webrtcFlowId = match ? match[1] : webrtcFlowArn;
      }
      if (chatFlowArn) {
        const match = chatFlowArn.match(/contact-flow\/([a-f0-9-]+)$/);
        chatFlowId = match ? match[1] : chatFlowArn;
      }
      
      if (webrtcFlowId || chatFlowId) {
        console.log('✅ Found Contact Flow IDs:');
        if (webrtcFlowId) console.log(`   WebRTC Flow ID: ${webrtcFlowId}`);
        if (chatFlowId) console.log(`   Chat Flow ID: ${chatFlowId}`);
        console.log('');
      } else {
        console.log('⚠️  Contact Flow IDs not found in Connect stack');
        console.log('   Available outputs:', Object.keys(connectOutputs).join(', '));
      }
    }
    
    // If nothing was found, skip
    if (!userPoolId && !clientId && !identityPoolId && !webrtcFlowId && !chatFlowId) {
      console.log('⚠️  No IDs found to update - skipping');
      return;
    }
    
    // Read current .env file
    const envPath = path.join(__dirname, '..', '.env');
    let envContent = fs.readFileSync(envPath, 'utf-8');
    
    // Update Cognito variables if found
    if (userPoolId && clientId && identityPoolId) {
      const hasCognitoVars = envContent.includes('COGNITO_USER_POOL_ID') ||
                             envContent.includes('COGNITO_CLIENT_ID') ||
                             envContent.includes('COGNITO_IDENTITY_POOL_ID');
      
      if (hasCognitoVars) {
        console.log('📝 Updating existing Cognito variables in .env');
        
        // Update existing values (including placeholders)
        envContent = envContent.replace(
          /^(COGNITO_USER_POOL_ID=).*/m,
          `$1${userPoolId}`
        );
        envContent = envContent.replace(
          /^(COGNITO_CLIENT_ID=).*/m,
          `$1${clientId}`
        );
        envContent = envContent.replace(
          /^(COGNITO_IDENTITY_POOL_ID=).*/m,
          `$1${identityPoolId}`
        );
      } else {
        console.log('📝 Adding Cognito variables to .env');
        
        // Add Cognito section after AWS configuration
        const cognitoSection = `
# ============================================================================
# COGNITO CONFIGURATION (Auto-generated from CDK deployment)
# ============================================================================
# Cognito User Pool ID
COGNITO_USER_POOL_ID=${userPoolId}

# Cognito User Pool Client ID
COGNITO_CLIENT_ID=${clientId}

# Cognito Identity Pool ID
COGNITO_IDENTITY_POOL_ID=${identityPoolId}
`;
        
        // Insert after AWS_REGION line
        envContent = envContent.replace(
          /(AWS_REGION=.*\n)/,
          `$1${cognitoSection}`
        );
      }
    }
    
    // Update Contact Flow IDs if found
    if (webrtcFlowId || chatFlowId) {
      const hasContactFlowVars = envContent.includes('AMAZON_CONNECT_WEBRTC_FLOW_ID') ||
                                  envContent.includes('AMAZON_CONNECT_CHAT_FLOW_ID');
      
      if (hasContactFlowVars) {
        console.log('📝 Updating existing Contact Flow IDs in .env');
        
        // Update existing values (including placeholders)
        if (webrtcFlowId) {
          envContent = envContent.replace(
            /^(AMAZON_CONNECT_WEBRTC_FLOW_ID=).*/m,
            `$1${webrtcFlowId}`
          );
        }
        if (chatFlowId) {
          envContent = envContent.replace(
            /^(AMAZON_CONNECT_CHAT_FLOW_ID=).*/m,
            `$1${chatFlowId}`
          );
        }
      } else {
        console.log('📝 Adding Contact Flow IDs to .env');
        
        // Add Contact Flow section after AMAZON_CONNECT_QUEUE_ID
        const contactFlowSection = `
# Contact Flow IDs (Auto-generated from CDK deployment)
${webrtcFlowId ? `AMAZON_CONNECT_WEBRTC_FLOW_ID=${webrtcFlowId}` : '# AMAZON_CONNECT_WEBRTC_FLOW_ID=<will be set after deployment>'}
${chatFlowId ? `AMAZON_CONNECT_CHAT_FLOW_ID=${chatFlowId}` : '# AMAZON_CONNECT_CHAT_FLOW_ID=<will be set after deployment>'}
`;
        
        // Insert after AMAZON_CONNECT_QUEUE_ID line
        envContent = envContent.replace(
          /(AMAZON_CONNECT_QUEUE_ID=.*\n)/,
          `$1${contactFlowSection}`
        );
      }
    }
    
    // Write updated .env file
    fs.writeFileSync(envPath, envContent);
    
    console.log('✅ Updated .env file with CDK outputs');
    if (userPoolId && clientId && identityPoolId) {
      console.log('   - Cognito IDs updated');
    }
    if (webrtcFlowId || chatFlowId) {
      console.log('   - Contact Flow IDs updated');
    }
    console.log('✅ Regenerating public/config.json with updated values...');
    console.log('');
    
  } catch (error) {
    console.error('❌ Error reading CDK outputs:', error.message);
    console.log('   Continuing anyway - you can manually add Cognito IDs to .env');
  }
}

updateEnvFromCdkOutputs();
